const audioContext = new (window.AudioContext || window.webkitAudioContext)();

function playNote(frequency, duration) {
    const oscillator = audioContext.createOscillator();
    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(frequency, audioContext.currentTime);
    oscillator.connect(audioContext.destination);
    oscillator.start();
    oscillator.stop(audioContext.currentTime + duration);
}

const notes = [
    { frequency: 293.66, key: 'D', measure: 1 },
    { frequency: 440, key: 'A', measure: 1 },
    { frequency: 246.94, key: 'Bm', measure: 2 },
    { frequency: 349.23, key: 'F#m', measure: 2 },
    { frequency: 196, key: 'G', measure: 3 },
    { frequency: 293.66, key: 'D', measure: 3 },
    { frequency: 196, key: 'G', measure: 4 },
    { frequency: 220, key: 'A', measure: 4 },
    { frequency: 739.99, key: 'F#5', measure: 5 },
    { frequency: 659.25, key: 'E5', measure: 6 },
    { frequency: 587.33, key: 'D5', measure: 7 },
    { frequency: 554.37, key: 'C#5', measure: 8 },
    { frequency: 493.88, key: 'B4', measure: 8 },
    { frequency: 440, key: 'A4', measure: 8 },
    { frequency: 493.88, key: 'B4', measure: 8 },
    { frequency: 554.37, key: 'C#5', measure: 8 }
];

let currentMeasure = 0;
let isPlaying = false;

function playMusic() {
    if (isPlaying) return;
    isPlaying = true;

    const playNextNote = () => {
        if (currentMeasure >= notes.length) {
            isPlaying = false;
            return;
        }

        const note = notes[currentMeasure];
        const keyElement = document.querySelector(`.key:contains(${note.key})`);
        const svgCircle = document.querySelector(`svg g[transform*="translate(${(note.measure - 1) * 100}, 50)"] circle`);

        if (keyElement && svgCircle) {
            keyElement.style.backgroundColor = 'yellow';
            svgCircle.setAttribute('fill', 'yellow');
            playNote(note.frequency, 0.5);

            setTimeout(() => {
                keyElement.style.backgroundColor = keyElement.classList.contains('black') ? 'black' : 'white';
                svgCircle.setAttribute('fill', 'black');
                currentMeasure++;
                playNextNote();
            }, 500); // Adjust the delay for the correct tempo
        }
    };

    playNextNote();
}

// Add event listener to the play button
const playButton = document.querySelector('.play-button');
playButton.addEventListener('click', playMusic);
